# AUTO-GENERATED by Claude Code
# Purpose: e2e test of the session log (services/ui/ui/debug_log.py): what is done in the
#          browser (a cell run, a slash command) reaches local/logs/ui/ui.jsonl, where
#          `ds ui debug` reads it. It only adds lines to that log.
# Usage: ds test e2e -k e2e_debug_log   (needs the app running; see conftest.py)
# ---------------------------------------------------------------------------
from __future__ import annotations

import secrets
import time
from typing import TYPE_CHECKING, Any

import pytest
from ds.cli import ui_debug

if TYPE_CHECKING:
    from collections.abc import Callable

    from tests.services.ui.e2e.conftest import App

WAIT_S = 10


def logged(found: Callable[[dict[str, Any]], bool]) -> dict[str, Any]:
    """The first record of the session log that matches, waited for (it fails after WAIT_S)."""
    deadline = time.monotonic() + WAIT_S
    while True:
        record = next(filter(found, ui_debug.read_records()), None)
        if record is not None:
            return record
        if time.monotonic() > deadline:
            pytest.fail("the record never reached the session log (ds ui debug)")
        time.sleep(0.1)


@pytest.mark.smoke
def test_a_cell_error_and_a_slash_command_reach_the_session_log(app: App) -> None:
    marker = f"e2e_marker_{secrets.token_hex(4)}"
    app.show("chat", "python")
    app.run_cell(f"{marker} = 1 / 0")
    cell = logged(lambda record: record.get("kind") == "cell" and marker in record.get("code", ""))
    assert "ZeroDivisionError" in cell["error"]
    assert cell["level"] == "ERROR"
    app.slash("/variables")
    row = logged(
        lambda record: (
            record.get("session") == cell["session"]
            and (record.get("kind"), record.get("source"), record.get("name")) == ("chat", "slash", "/variables")
        )
    )
    assert row["at"] >= cell["at"]
